con:config.script:
/***********SCRIPT LOAD EMISOR********/
import imports.Index;
import imports.Cellxlsx;
import java.util.Random;

def excelFilePath = "C:\\Import.xlsx" //ruta absoluta

def propertiesStepNameEmi = "Emisor" //Properties EMISOR
def propertiesStepNameRec = "Receptor" //Properties RECEPTOP

/*********Carga de propiedades**********/
def loadPropertiesEmi = testRunner.testCase.getTestStepByName(propertiesStepNameEmi);
def loadPropertiesRec = testRunner.testCase.getTestStepByName(propertiesStepNameRec);

//Condicion para evaluar Emi
if(loadPropertiesEmi == null){
	log.info("Error,: el paso de prueba al que intenta cargar valores no fue encontrado '${propertiesStepNameEmi}' ")	
	return //Terminar la ejecucion en caso de que no se encuentre el paso 
}

//Condicional para evaluar Rec
if(loadPropertiesRec == null){
	log.info("Error: el paso de prueba: '${propertiesStepNameRec}' al que intenta cargar valores no fue encontrado ")
	return //Terminar la ejecucion en caso de q no se encuentre el paso 	
}

/********Lectura de Datos Excel Aplicando el metodo Random******************/

//variable que identifica la importacion de las filas en la propiedad 'Emisor'
def registroEmi = Index.readExcelData(excelFilePath) 

context.ListEmisor = registroEmi;

log.info "----------------------" + context.ListEmisor [0].nombre


//variable que indentifica la impor de las filas en las propiedad 'Rec'
def registroRec = Index.readExcelData(excelFilePath)

log.info("--------Datos Importados: (${registroEmi.size()}) registros para Emisor--------") //Imprimir los registros cargados en contexto Emi
log.info("\n--------Datos Importados: (${registroRec.size()}) registros para Receptor--------") //Imprimir los registros cargados en contexto Rec

//Condicional que evalua si hay registros en el formato excel
if(registroEmi .isEmpty()){
	log.info("Error: no se encontraron datos en su hoja de excel, verifique he intente de nuevo")
	return //Terminar la ejecucion
}

/*****Incorporacion de random para Emisor********/
def randomIndex = new Random().nextInt(registroEmi.size()); //Instanciar el metodo random
log.info("Indice de fila generado para Emisor:   ${randomIndex} ")

/*******Asignacion de propiedades Emi******/
def  selectedRow = registroEmi.get(randomIndex)

//Acceder directamente a los atributos de la clase Cellxlsx ademas de contextualizar los datos en las properties Emi
loadPropertiesEmi .setPropertyValue("id", selectedRow .getId())
loadPropertiesEmi .setPropertyValue("nombre", selectedRow .getNombre())
loadPropertiesEmi .setPropertyValue("codBanco", selectedRow .getCodBanco())
loadPropertiesEmi .setPropertyValue("tld", selectedRow .getTlf())
loadPropertiesEmi .setPropertyValue("cuenta", selectedRow .getCuenta())

//Imprimir resultados en los log 
log.info("---------Datos de la fila con índice: ${randomIndex} cargados exitosamente en la propertie Emisor:------")
log.info("ID: ${selectedRow.getId()}")
log.info("Nombre: ${selectedRow.getNombre()}")
log.info("CodBanco: ${selectedRow.getCodBanco()}")
log.info("Teléfono: ${selectedRow.getTlf()}")
log.info("Cuenta: ${selectedRow.getCuenta()}")

/*****Instancia random para Receptor********/
def randomIndexRec = new Random().nextInt(registroRec.size());
log.info("Indice de fila generado para Receptor:   ${randomIndexRec} ")

/*******Asignacion de propiedades Rec******/
def selectedRowRec = registroRec.get(randomIndexRec); //Instanciar el metodo random
//Acceder directamente a los atributos de la clase Cellxlsx ademas de contextualizar los datos en las properties Rec
loadPropertiesRec .setPropertyValue("id", selectedRowRec .getId())
loadPropertiesRec .setPropertyValue("nombre", selectedRowRec .getNombre())
loadPropertiesRec .setPropertyValue("codBanco", selectedRowRec .getCodBanco())
loadPropertiesRec .setPropertyValue("tlf", selectedRowRec .getTlf())
loadPropertiesRec .setPropertyValue("cuenta", selectedRowRec .getCuenta())

context.myVariable = "";

//Imprimir resultados en los log 
log.info("---------Datos de la fila con índice: ${randomIndex} cargados exitosamente en la propertie Receptor:------")
log.info("ID: ${selectedRowRec.getId()}")
log.info("Nombre: ${selectedRowRec.getNombre()}")
log.info("CodBanco: ${selectedRowRec.getCodBanco()}")
log.info("Teléfono: ${selectedRowRec.getTlf()}")
log.info("Cuenta: ${selectedRowRec.getCuenta()}")

con:configuration.scriptText:
//import org.bson.Document
import groovy.json.JsonSlurper;
import Utiliti.SYPAGOBancaribe;

sleep(2000) //Aplica un retardo de 2sg;

def ClienteBancaribe =  new SYPAGOBancaribe();

    def requestContent = new String(messageExchange.rawRequestData)
    def jsonStartIndex = requestContent.indexOf("{")
    def jsonContent = requestContent.substring(jsonStartIndex)
    log.info  jsonContent
    def json = new groovy.json.JsonSlurper().parseText(jsonContent)

    log.info json.TransactionId
    def a = ClienteBancaribe.geyStsusReports("sycom_gateway_user","3b17-0e38206Pae-88_@fb8476dff92f271A7C","http://10.0.62.20:8086/sypago/gateway/api/v1/solest",json.TransactionId);
    log.info(a);

    def jsonR = new groovy.json.JsonSlurper().parseText(a)

    log.info jsonR.TrnStRp.TxSts

    def TxSts = jsonR.TrnStRp.TxSts; 
	assert  TxSts== "RJCT"

	def Rsn = jsonR.TrnStRp.Rsn; 
	//log.info Rsn
	assert  Rsn== "MD21" //Assert condicion que verifica que el valor sea igual a lo definido

con:config.script:
import java.util.Random

//Instanciar el metodo random
Random randomTrnasactionId =new Random();

//Rango de volumen 13 digitos
long min = 1111111111111L;
long max = 9999999999999L;

//Calculo de rando de digitos
long resulAletorio = randomTrnasactionId.nextLong(max - min +1) + min;

/*******Cargar valor al contexto Properti Emisor*******/

def loadTransactionId = testRunner.testCase.getTestStepByName("Emisor");

//Validar que el paso de prueba este generado
if(loadTransactionId == null){
	log.info("Error, el paso de prueba que intenta llamar: ${loadTransactionId} no esta disponible, valide que este generado he intente de nuevo")
	return //Finala la ejecucion de validacion
}

//Contextualizar TrnasactionId aplicando el metodo random: en la propertie Emisor
loadTransactionId .setPropertyValue("TrnasactionId", "${resulAletorio}")

log.info("El valor generado para TransactionId es: ${resulAletorio}")

