	def Rns = jsonR.TrnStRp.Rns
	log.info Rns
	assert Rns == "AC00"

con:config.script:
//SCRIPTS PARA PASAR A CONTEXTO GLOBAL LA DATA IMPORTADA CARGADA DESDE EXCEL APLICANDO EL METODO RANDOM

/*
*  Para invocar a las variables desde el msj JSON de forma statica haciendo se debe hacer referencia al numero del elemento deseado
*  
*  Ejm Statico de una etiqueta: "${=context.variableContextGlobal [0].nombre}"
*  Ejm Dinamico de una etiqueta "${=context.variableContextGlobal [${context.}]}"	
*/

/***********SCRIPT RECEPTOR IBP BANCARIBE******************/
import imports.Cellxlsx;
import imports.Index;
import java.util.Random;

def excelFilePath = "C:\\Import.xlsx"; //Ruta absoluta

def ReceptorBancaribe = Index.readExcelData(excelFilePath,0);

/****Instancia Random****/
def randomBancaribe = new Random().nextInt(ReceptorBancaribe.size()); //Definicion de las filas dentro de la hola
log.info("Indice de fila generado: ${randomBancaribe}" );

//Contextualizar Lista de variables globales
context.listRecepBancaribe = ReceptorBancaribe;
log.info(context.listRecepBancaribe); //.nombre[0] 

//Contextualizar valor generado por el metodo random
context.ListRandom = randomBancaribe;
//log.info(context.ListRandom)

//SCRIPTS PARA PASAR A CONTEXTO GLOBAL LA DATA IMPORTADA CARGADA DESDE EXCEL APLICANDO EL METODO RANDOM

/***********SCRIPT RECEPTOR******************/
import imports.Cellxlsx;
import imports.Index;
import java.util.Random;

def excelFilePath = "C:\\Import.xlsx" //Ruta absoluta

/*****Lectura del excel*******/
//Definicion de el numero de hoja donde realiza extraera los datos
def ReceptorIBPs = Index.readExcelData(excelFilePath, 1);

/*********Instancia Random*************/
// Corregido: Usar nextInt(bound) para generar un número aleatorio dentro del rango.
def randomIBPs = new Random().nextInt(ReceptorIBPs.size()); //Define las filas dentro de la hoja
log.info("Indice de fila generado: ${randomIBPs}")

//Variable contextualizada global
context.ListIBPs = ReceptorIBPs;
log.info(context.ListIBPs); //.nombre[0]

//Variable para contextualizar Lista random
context.ListRandom = randomIBPs;
log.info(context.ListRandom);

/************GENERADOR DE TRANSACTIONID CARACTERES ESPECIALES*****************/
import java.util.Random;

//Instanciar random
Random idRandom = new Random();
 //Rango de volumen 6
 long min = 111111;
 long max = 999999;

//Calculo de random
long resultadoRandom = idRandom.nextLong(max - min) + 1

def caracterHead = "#^"
def caracterFooter = "zY#"
def transactionId = caracterHead + resultadoRandom + caracterFooter
//log.info transactionId
//CARGAR EL VALOR AL CONTEXTO GLOBAL
context.transIdChars = transactionId;

//APROVECHAMOS EL RANDOM Y GENERAMOS UN N# DE CNTRATO ALETORIO
def charH = "C";
def randomCMCN = charH + resultadoRandom;
context.randomCmcn = randomCMCN;
//log.info randomCMCN

/********************GENERADOR DE TRANSACTION ID RANGO > 11******************************/
//Instanciar Random
Random idMayorRandom = new Random();

//Rango de volumen 14
long minI = 11111111111111;
long maxI = 99999999999999;

//Calculo del random
long resultadoMayorRandom = idMayorRandom.nextLong(maxI - minI) + 1

def complementoI = "zTwF"
def complementoII = "Yz"
def transactioIdMayor = complementoI + resultadoMayorRandom + complementoII;
//log.info("TransactionId: ${transactioIdMayor}")\

//CARGAR EL VALOR AL CONTEXTO GLOBAL
context.transIdMayor = transactioIdMayor;

/*********GENERADOR DE ESTRING > 16 PARA UserReference*********/
import java.util.Random;
import Labels.GeneratorUserReferenceId;

//Variable para almacer el string
def longitudGroovy = 20;

//Llamamos al método estático directamente usando el nombre del paquete y la clase
def codigoGenerado = Labels.GeneratorUserReferenceId.GeneratorChart(longitudGroovy)
context.UserRefId = codigoGenerado; //Contexto


/*****************GENERADOR DE STRINGS PARA Nm > 200*********/
//Variable para almacenar el string de Nm
def longitudNm = 351;

//Llamado del metodo
def generatorNm = Labels.GeneratorUserReferenceId.GeneratorChart(longitudNm);
context.chartNm = generatorNm;

