*/

/***********SCRIPT RECEPTOR IBP BANCARIBE******************/
import imports.Cellxlsx;
import imports.Index;
import java.util.Random;

def excelFilePath = "C:\\Import.xlsx"; //Ruta absoluta

def ReceptorIBPs = Index.readExcelData(excelFilePath,2);

/****Instancia Random****/
def randomIBPs = new Random().nextInt(ReceptorIBPs.size()); //Definicion de las filas dentro de la hola
log.info("Indice de fila generado: ${ReceptorIBPs}" );

//Contextualizar Lista de variables globales
context.listRecepIBPs = ReceptorIBPs;
log.info(context.listRecepIBPs); //.nombre[0] 

//Contextualizar valor generado por el metodo random
context.ListRandom = randomIBPs;
//log.info(context.ListRandom)

import java.util.Random;
import Labels.TransactionIdGV2;

//Variable para almacer el string
def longitudGroovy = 8;

//Llamamos al método estático directamente usando el nombre del paquete y la clase
def codigoGenerado = Labels.TransactionIdGV2.Transaction(longitudGroovy)
context.transactionId = codigoGenerado; //Contexto

