con:configuration.scriptText:
import groovy.json.JsonSlurper;
import Utiliti.GatewayV2;


sleep(2000) // Aplica un retardo de 2 segundos;

// Instancia de la clase Java GatewayV2
def ClienteBancaribe = new GatewayV2();

//Llamar el valor de TransactionId
def requestContent = new String(messageExchange.rawRequestData)
def jsonStartIndex = requestContent.indexOf("{")
def jsonContent = requestContent.substring(jsonStartIndex)
log.info jsonContent
def json = new groovy.json.JsonSlurper().parseText(jsonContent)

// Definir el transaction_id que deseas consultar.
// Este debe coincidir con el ID que esperas en la respuesta.
def transactionIdToQuery = json.TransactionId; // Usamos el ID de ejemplo que nos diste


// El endpoint ahora se pasa como una URL base y el transaction_id se añade internamente.
def responseJsonString = ClienteBancaribe.getStatusReports(
    "sygateway_user",
    "sB5I2lRO5Jxh1ia47S7KvnyLR",
    "https://10.0.62.20:8088/api/v1/transaction/", // URL base
    transactionIdToQuery // El transaction_id se agrega como parámetro de la URL dentro del método Java
);

log.info("Respuesta completa del servidor: " + responseJsonString);

// Parsea la cadena JSON de la respuesta del servidor
def jsonResponse = new groovy.json.JsonSlurper().parseText(responseJsonString);

// --- Asersiones basadas en la estructura JSON esperada ---

/**** CONDICIONAL PARA VALIDAR ACCP o MD15 ****/
// Acceder directamente a "Status" y "RejectedCode" desde la raíz del JSON
def status = jsonResponse.Status;
def rejectedCode = jsonResponse.RejectedCode;

log.info("Estado de la transacción: " + status);
log.info("Código de rechazo: " + rejectedCode);

// Define la condición de éxito
def isSuccessful = status == "ACCP" || rejectedCode == "MD15";

// La aserción fallará si 'isSuccessful' es falso.
assert isSuccessful : "El estado fue: ${status} y el código de rechazo fue: ${rejectedCode}";

